import{_ as o,a0 as s,w as u,s as m,ao as l,I as r,a1 as n,A as e,x as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"Terminator：一款一个窗口包含多个终端的 Linux 终端仿真器 | LCTT x X-CMD","titleTemplate":false,"description":"Terminator：一款一个窗口包含多个终端的 Linux 终端仿真器 | LCTT (201610) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Terminator：一款一个窗口包含多个终端的 Linux 终端仿真器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Terminator：一款一个窗口包含多个终端的 Linux 终端仿真器 | LCTT (201610) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201610/20160724  Terminator A Linux Terminal Emulator With Multiple Terminals In One Window","title":"Terminator：一款一个窗口包含多个终端的 Linux 终端仿真器","tag":"201610","desc":""},"relativePath":"201610/20160724  Terminator A Linux Terminal Emulator With Multiple Terminals In One Window.md","filePath":"[post].md"}'),p={name:"201610/20160724  Terminator A Linux Terminal Emulator With Multiple Terminals In One Window.md"};function d(h,t,T,x,g,b){const a=s("Link");return u(),m("div",null,[t[17]||(t[17]=l('<h1 id="terminator-一款一个窗口包含多个终端的-linux-终端仿真器" tabindex="-1">Terminator：一款一个窗口包含多个终端的 Linux 终端仿真器 <a class="header-anchor" href="#terminator-一款一个窗口包含多个终端的-linux-终端仿真器" aria-label="Permalink to “Terminator：一款一个窗口包含多个终端的 Linux 终端仿真器”">​</a></h1><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/lots-of-terminals-in-terminator_1.jpg?659" alt=""></p><p>为了通过命令行和系统互动，每一款 Linux 发行版都有一款默认的终端仿真器。但是，默认的终端应用可能不适合你。为了大幅提升你工作的速度，有好多款终端应用提供了更多的功能，可以同时执行更多的任务。这些有用的终端仿真器就包括 Terminator，这是一款 Linux 系统下支持多窗口的自由开源的终端仿真器。</p><h3 id="什么是-linux-终端仿真器" tabindex="-1">什么是 Linux 终端仿真器 <a class="header-anchor" href="#什么是-linux-终端仿真器" aria-label="Permalink to “什么是 Linux 终端仿真器”">​</a></h3><p>Linux 终端仿真器是一个让你和 shell 交互的程序。所有的 Linux 发行版都会自带一款 Linux 终端应用让你向 shell 传递命令。</p><h3 id="terminator-一款自由开源的-linux-终端应用" tabindex="-1">Terminator，一款自由开源的 Linux 终端应用 <a class="header-anchor" href="#terminator-一款自由开源的-linux-终端应用" aria-label="Permalink to “Terminator，一款自由开源的 Linux 终端应用”">​</a></h3><p>Terminator 是一款 Linux 终端模拟器，提供了你的默认的终端应用不支持的多个特性。它提供了在一个窗口创建多个终端的功能，以加快你的工作速度。除了多窗口外，它也允许你修改其它特性，例如字体、字体颜色、背景色等等。让我们看看我们如何安装它，并且如何在不同的 Linux 发行版下使用 Terminator。</p><h3 id="如何在-linux-下安装-terminator" tabindex="-1">如何在 Linux 下安装 Terminator？ <a class="header-anchor" href="#如何在-linux-下安装-terminator" aria-label="Permalink to “如何在 Linux 下安装 Terminator？”">​</a></h3><h4 id="在基于-ubuntu-的发行版上安装-terminator" tabindex="-1">在基于 Ubuntu 的发行版上安装 Terminator <a class="header-anchor" href="#在基于-ubuntu-的发行版上安装-terminator" aria-label="Permalink to “在基于 Ubuntu 的发行版上安装 Terminator”">​</a></h4><p>Terminator 在默认的 Ubuntu 仓库就可以使用。所以你不需要添加额外的 PPA。只需要使用 APT 或者“软件应用”在 Ubuntu 下直接安装。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install terminator</span></span></code></pre></div><p>假如你的默认的仓库中 Terminator 不可用，只需要使用源码编译 Terminator 即可。</p>',12)),r("ul",null,[r("li",null,[n(a,{href:"https://launchpad.net/terminator/+download"},{default:e(()=>[...t[0]||(t[0]=[i("下载源码",-1)])]),_:1})])]),t[18]||(t[18]=l('<p>下载 Terminator 源码并且解压到你的桌面。现在打开你的默认的终端，然后 <code>cd</code> 到解压的目录。</p><p>现在就可以使用下面的命令来安装 Terminator 了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ./setup.py install</span></span></code></pre></div><h4 id="在-fedora-及衍生的操作系统上安装-terminator" tabindex="-1">在 Fedora 及衍生的操作系统上安装 Terminator <a class="header-anchor" href="#在-fedora-及衍生的操作系统上安装-terminator" aria-label="Permalink to “在 Fedora 及衍生的操作系统上安装 Terminator”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dnf install terminator</span></span></code></pre></div><h4 id="在-opensuse-上安装-terminator" tabindex="-1">在 OpenSuse 上安装 Terminator <a class="header-anchor" href="#在-opensuse-上安装-terminator" aria-label="Permalink to “在 OpenSuse 上安装 Terminator”">​</a></h4>',6)),r("p",null,[t[2]||(t[2]=i("参见此文：",-1)),n(a,{href:"http://software.opensuse.org/download.html?project=home%3AKorbi123&package=terminator"},{default:e(()=>[...t[1]||(t[1]=[i("在 OPENSUSE 上安装",-1)])]),_:1}),t[3]||(t[3]=i("。",-1))]),t[19]||(t[19]=l('<h3 id="如何在一个窗口使用多个终端" tabindex="-1">如何在一个窗口使用多个终端？ <a class="header-anchor" href="#如何在一个窗口使用多个终端" aria-label="Permalink to “如何在一个窗口使用多个终端？”">​</a></h3><p>安装好 Terminator 之后，你可以简单的在一个窗口打开多个终端。只需要右键点击并切分。</p><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/multiple-terminals-in-terminator_orig.jpg" alt=""></p><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/multiple-terminals-in-terminator-emulator.jpg?697" alt=""></p><p>只要你愿意，你可以创建尽可能多的终端，只要你能管理得过来。</p><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/lots-of-terminals-in-terminator.jpg?706" alt=""></p><h3 id="定制终端" tabindex="-1">定制终端 <a class="header-anchor" href="#定制终端" aria-label="Permalink to “定制终端”">​</a></h3><p>右键点击终端，并单击属性。现在你可以定制字体、字体颜色、标题颜色和背景，还有终端字体颜色和背景。</p><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/customize-terminator-interface.jpg?702" alt=""></p><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/free-terminal-emulator_orig.jpg" alt=""></p><h3 id="结论-什么是你最喜欢的终端模拟器" tabindex="-1">结论：什么是你最喜欢的终端模拟器 <a class="header-anchor" href="#结论-什么是你最喜欢的终端模拟器" aria-label="Permalink to “结论：什么是你最喜欢的终端模拟器”">​</a></h3><p>Terminator 是一款先进的终端模拟器，它可以让你自定义界面。如果你还没有从你默认的终端模拟器中切换过来的话，你可以尝试一下它。我知道你将会喜欢上它。如果你正在使用其他的自由开源的终端模拟器的话，请让我们知道你最喜欢的那一款。不要忘了和你的朋友分享这篇文章。或许你的朋友正在寻找类似的东西。</p><hr>',13)),r("p",null,[t[5]||(t[5]=i("via: ",-1)),n(a,{href:"http://www.linuxandubuntu.com/home/terminator-a-linux-terminal-emulator-with-multiple-terminals-in-one-window"},{default:e(()=>[...t[4]||(t[4]=[i("http://www.linuxandubuntu.com/home/terminator-a-linux-terminal-emulator-with-multiple-terminals-in-one-window",-1)])]),_:1})]),r("p",null,[t[9]||(t[9]=i("作者：",-1)),n(a,{href:"http://www.linuxandubuntu.com/home/terminator-a-linux-terminal-emulator-with-multiple-terminals-in-one-window"},{default:e(()=>[...t[6]||(t[6]=[i("author",-1)])]),_:1}),t[10]||(t[10]=i(" 译者：",-1)),n(a,{href:"https://github.com/yangmingming"},{default:e(()=>[...t[7]||(t[7]=[i("yangmingming",-1)])]),_:1}),t[11]||(t[11]=i(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:e(()=>[...t[8]||(t[8]=[i("wxy",-1)])]),_:1})]),r("p",null,[t[14]||(t[14]=i("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[12]||(t[12]=[i("LCTT",-1)])]),_:1}),t[15]||(t[15]=i(" 原创编译，",-1)),n(a,{href:"https://linux.cn/"},{default:e(()=>[...t[13]||(t[13]=[i("Linux中国",-1)])]),_:1}),t[16]||(t[16]=i(" 荣誉推出",-1))])])}const L=o(p,[["render",d]]);export{k as __pageData,L as default};
